const b64=data=>Buffer.from(typeof data==='string'?data:JSON.stringify(data)).toString('base64url');
await test('Firebase JWTは署名・発行元・期限を検証',async()=>{const pair=await crypto.subtle.generateKey({name:'RSASSA-PKCS1-v1_5',modulusLength:2048,publicExponent:new Uint8Array([1,0,1]),hash:'SHA-256'},true,['sign','verify']);const jwk=await crypto.subtle.exportKey('jwk',pair.publicKey);jwk.kid='test-key';const original=globalThis.fetch;globalThis.fetch=async()=>new Response(JSON.stringify({keys:[jwk]}));try{const now=Math.floor(Date.now()/1000);const create=async changes=>{const payload={aud:'test-project',iss:'https://securetoken.google.com/test-project',sub:'teacher',exp:now+3600,iat:now,firebase:{sign_in_provider:'google.com'},...changes};const data=b64({alg:'RS256',kid:'test-key'})+'.'+b64(payload);const signature=await crypto.subtle.sign('RSASSA-PKCS1-v1_5',pair.privateKey,new TextEncoder().encode(data));return data+'.'+Buffer.from(signature).toString('base64url');};assert.equal((await verifyToken(await create({}),'test-project')).uid,'teacher');const env={ALLOWED_ORIGIN:'https://example.test',FIREBASE_PROJECT:'test-project',ROOMS:{get(){throw Error('No DO allowed');}},AI:{run(){throw Error('No AI for a registered phrase');}}};const translated=await workerApi.fetch(new Request('https://api.test/translate',{method:'POST',headers:{Origin:'https://example.test',Authorization:'Bearer '+await create({}),'Content-Type':'application/json'},body:JSON.stringify({text:catalog.phrases[0].jaText,source:'ja',targets:['en','pt']})}),env);assert.equal(translated.status,200);assert.equal((await translated.json()).translations.en,catalog.phrases[0].enText);await assert.rejects(async()=>verifyToken(await create({exp:now-1}),'test-project'));await assert.rejects(async()=>verifyToken(await create({aud:'other'}),'test-project'));await assert.rejects(()=>verifyToken('fake','test-project'));}finally{globalThis.fetch=original;}});
function fixture(mode='lesson',role='guest'){const db=new Map([['room',{mode,owner:'owner',key:'secret',expires:Date.now()+ROOM_TTL,unit:'数学'}]]),messages=[];const a={uid:role==='teacher'?'owner':'guest',id:'a'.repeat(32),name:'テスト',role,language:'ja',viewLanguage:'pt',expires:Date.now()+3600000,window:Date.now(),count:0};const ws={deserializeAttachment:()=>a,serializeAttachment:x=>Object.assign(a,x),send:s=>messages.push(JSON.parse(s)),close(){}};const sockets=[ws];const jobs=[];const ctx={storage:{get:async k=>db.get(k),put:async(k,v)=>db.set(k,v),getAlarm:async()=>0,setAlarm:async()=>{},list:async({prefix})=>new Map([...db].filter(([k])=>k.startsWith(prefix))),deleteAll:async()=>db.clear()},getWebSockets:()=>sockets,waitUntil:p=>jobs.push(p)};const env={FIREBASE_PROJECT:'test-project',AI:{async run(){return {response:'{"en":"x is 3","pt":"x é 3"}'};}}};return {room:new TranslationRoom(ctx,env),ws,db,messages,jobs,sockets};}

function addStudent(f){const attachment={...f.ws.deserializeAttachment(),uid:'student',id:'b'.repeat(32),role:'guest',language:'pt',viewLanguage:'pt'},messages=[];const ws={deserializeAttachment:()=>attachment,serializeAttachment:value=>Object.assign(attachment,value),send:text=>messages.push(JSON.parse(text)),close(){}};f.sockets.push(ws);return {ws,attachment,messages};}
await test('先生の言語変更は本人へ通知し参加者一覧にも反映・AI呼び出しなし',async()=>{const f=fixture('lesson','teacher'),student=addStudent(f);await f.room.webSocketMessage(f.ws,JSON.stringify({type:'participant_language',to:student.attachment.id,language:'en'}));assert.equal(student.attachment.language,'en');assert.equal(student.attachment.viewLanguage,'en');assert.ok(student.messages.some(m=>m.type==='language_changed'&&m.language==='en'));assert.equal(student.messages.find(m=>m.type==='participants').participants.find(p=>p.id===student.attachment.id).viewLanguage,'en');assert.equal(f.jobs.length,0);});
