function codeStorage(){const db=new Map();let alarm=0,tail=Promise.resolve();const storage={get:async k=>db.get(k),put:async(k,v)=>db.set(k,v),delete:async k=>db.delete(k),list:async({prefix})=>new Map([...db].filter(([k])=>k.startsWith(prefix))),getAlarm:async()=>alarm,setAlarm:async t=>{alarm=t;}};storage.transaction=fn=>{const result=tail.then(()=>fn(storage));tail=result.catch(()=>{});return result;};return {db,storage};}
await test('4桁IDは同時作成と乱数衝突でも重複しない',async()=>{const f=codeStorage(),codes=new LessonCodes(f.storage,()=>1000,()=>0);const rooms=await Promise.all(Array.from({length:50},(_,i)=>codes.allocate({id:'room'+i,key:'key'+i})));assert.equal(rooms[0].code,'0000');assert.equal(new Set(rooms.map(r=>r.code)).size,50);assert.equal(rooms[0].expires,1000+ROOM_TTL);assert.equal((await codes.lookup('００００')).id,'room0');});
await test('24時間後のIDは再利用でき、古い履歴へ接続しない',async()=>{const f=codeStorage();let now=1000;const codes=new LessonCodes(f.storage,()=>now,()=>0),old=await codes.allocate({id:'old',key:'old-key'});now+=ROOM_TTL;await assert.rejects(()=>codes.lookup(old.code));const next=await codes.allocate({id:'new',key:'new-key'});assert.equal(next.code,old.code);assert.equal((await codes.lookup(next.code)).key,'new-key');await codes.release(old.code,'old');assert.equal((await codes.lookup(next.code)).id,'new');now+=ROOM_TTL;await codes.cleanup();assert.equal(f.db.has('code:0000'),false);});
