await test('退室通知の直後に参加者から削除し、Close再通知でも二重通知しない',async()=>{const f=fixture('interpreter','teacher'),received=[],a={uid:'other',id:'b'.repeat(32),language:'pt',viewLanguage:'pt',name:'相手',role:'guest'},other={readyState:1,deserializeAttachment:()=>a,send:s=>received.push(JSON.parse(s))};f.room.ctx.getWebSockets=()=>[f.ws,other];await f.room.webSocketMessage(f.ws,JSON.stringify({type:'leave'}));assert.equal(f.room.participants().length,1);assert.equal(received.at(-1).type,'participants');assert.deepEqual(received.at(-1).participants.map(p=>p.id),[a.id]);const notices=received.length;await f.room.webSocketClose(f.ws);assert.equal(received.length,notices);other.readyState=2;assert.equal(f.room.participants().length,0);});
