await test('診断APIとルーム用CORSヘッダーは指定の接続元だけを許可する',async()=>{const origin='https://hiroakiaa.github.io',env={ALLOWED_ORIGIN:origin};const preflight=await workerApi.fetch(new Request('https://api.example/health',{method:'OPTIONS',headers:{Origin:origin,'Access-Control-Request-Method':'POST','Access-Control-Request-Headers':'authorization,content-type'}}),env);assert.equal(preflight.status,204);assert.equal(preflight.headers.get('Access-Control-Allow-Origin'),origin);assert.match(preflight.headers.get('Access-Control-Allow-Headers'),/Authorization/);const response=await workerApi.fetch(new Request('https://api.example/health',{method:'POST',headers:{Origin:origin,Authorization:'Bearer connectivity-check','Content-Type':'application/json'},body:'{}'}),env);assert.equal((await response.json()).ok,true);const rejected=await workerApi.fetch(new Request('https://api.example/health',{method:'OPTIONS',headers:{Origin:'https://other.example'}}),env);assert.equal(rejected.status,403);assert.equal(rejected.headers.get('Access-Control-Allow-Origin'),null);});
